mapper.insert:
insert into workspace (
    id, name, status, created_by, updated_by, created_at, updated_at
) values (
    #{id}, #{name}, #{status}, #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}
)

insert into workspace_member (
    workspace_id, user_id, role, status, created_by, updated_by, created_at, updated_at
) values (
    #{workspaceId}, #{userId}, #{role}, #{status}, #{createdBy}, #{updatedBy}, #{createdAt}, #{updatedAt}
)

mapper.update:
update workspace_member
set role = #{role}, updated_by = #{updatedBy}, updated_at = #{updatedAt}
where workspace_id = #{workspaceId}
  and user_id = #{userId}
  and status = 'ACTIVE'

update workspace_member
set status = 'REMOVED', updated_by = #{updatedBy}, updated_at = #{updatedAt}
where workspace_id = #{workspaceId}
  and user_id = #{userId}
  and status = 'ACTIVE'
